def min_presidios(n, colors):
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    prefix = [0] * (n + 1)
    color_count = {}

    for i in range(1, n + 1):
        color_count[colors[i - 1]] = color_count.get(colors[i - 1], 0) + 1
        prefix[i] = prefix[i - 1] + color_count[colors[i - 1]]
        for k in range(1, n + 1):
            if prefix[i] <= k:
                dp[k] = min(dp[k], dp[prefix[i]] + 1)

    return dp

