def game_play(papers):
    n = len(papers)
    dp = [[[float('-inf')] * 3 for _ in range(n)] for __ in range(n)]

    for length in range(1, n):
        for start in range(n - length):
            end = start + length
            if start == 0:
                dp[start][end][0] = papers[end]
            else:
                dp[start][end][0] = max(dp[start][end-1][1] + papers[end], dp[start][end-1][0])

            if end - start == 1 and start != n - 1:
                dp[start][end][1] = papers[start] + papers[end]
            elif start != n - 1:
                dp[start][end][1] = max(dp[start+1][end][0], dp[start+1][end][1])

    for i in range(n):
        dp[i][i][0] = dp[i][i][1]

    return dp[0][n-1][0]

def calculate_earnings(papers):
    n = len(papers)
    total_income = sum(papers)
    return total_income - game_play(papers)

