from itertools import combinations

def is_pentagram(points):
    # Check if four points A, B, C, D form a parallelogram assuming A, D are opposite points
    M = [(points[i][0] - points[0][0]) * (points[1][1] - points[3][1]) - \
         (points[i][1] - points[0][1]) * (points[1][0] - points[3][0]) for i in range(4)]
    return max(M) == min(M)

def count_pentagrams(points):
    count = 0
    for combo in combinations(points, 5):
        if is_pentagram(combo):
            count += 1
    return count

