                continue

            overlap = adj[i] & adj[j]
            if len(group_map[overlap.pop()]) > 0:
                group_map[i] = group_map[j] = min(group_map[i], group_map[j])

            new_groups = sorted([-low, num] if num > low else [num, low] for low, num in [[min(adj[i]), max(adj[i])], [min(adj[j]), max(adj[j])]])

            while new_groups[1] in (adj[i], adj[j]):
                new_groups[1] -= 1

            for group in sorted(set(adj[i] - set(new_groups)) | sorted(set(adj[j] - set(new_groups))):
