from collections import defaultdict

def find_least_common_multiple(nums):
    seen = defaultdict(set)
    for i, n in nums:
        if i != 1:  # Skip the first number for geometric progression
            seen[n].add(i // n)

    min_mult = float('inf')
    for i in range(1, n + 1):
        for n1 in seen[1]:
            for n2 in seen[i]:
                min_mult = min(min_mult, i * n1 * n2)

    return min_mult if min_mult < float('inf') else -1

