from collections import deque, defaultdict
from typing import List

def count_badly_painted_regions(n: int, m: int, x: int, paint_layers_row: List[int], paint_layers_column: List[int]) -> int:
    # Initialize the map with -1 values to represent unvisited cells
    visited = [[-1] * m for _ in range(n)]
    count_regions = 0

    for i in range(n):
        for j in range(m):
            if visited[i][j] == -1:
                queue = deque([(i, j)])
                count_regions += 1
                while queue:
                    row, col = queue.popleft()
                    # Check if the cell is badly painted
                    if paint_layers_row[row] + paint_layers_column[col] > x:
                        visited[row][col] = 0
                        for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                            r, c = row + dr, col + dc
                            if 0 <= r < n and 0 <= c < m and visited[r][c] == -1:
                                visited[r][c] = 0
                                queue.append((r, c))
    return count_regions
