def mod_exp(x, n, mod):
    result = 1
    x = x % mod
    while n > 0:
        if n % 2 == 1:
            result = (result * x) % mod
        x = (x * x) % mod
        n = n // 2
    return result

def bitwise_and_sum(n, r):
    if n > r:
        return mod_exp(2, r, (10**9 + 7)) - mod_exp(2, n - 1, (10**9 + 7))
    else:
        return mod_exp(2, r + 1, (10**9 + 7)) - mod_exp(2, n, (10**9 + 7))

