from math import gcd
from functools import reduce
from itertools import combinations

def lcm(a, b):
    return a * b // gcd(a, b)

def calculate_highest_common_factor(heights):
    highest_common_factor = heights[0]
    for height in heights:
        highest_common_factor = lcm(highest_common_factor, height)
    return highest_common_factor

def calculate_pairs(heights):
    n = len(heights)
    highest_common_factor = calculate_highest_common_factor(heights)
    divisors = {d for d in range(1, n+1) if not highest_common_factor % d}
    for n_copies in divisors:
        count = [0] * n
        for i in range(n):
            count[i % n_copies] += heights[i]
        max_value = max(count)
        min_value = min(count)
        pairs = 0
        for count_a in count:
            pairs += count_a * (max_value - count_a)
        pairs //= 2
        divisors -= {n_copies}
    return sum(divisors)

