from collections import deque

def compute_difference(n, incomes):
    left_deque = deque()
    right_deque = deque()

    if n == 1:
        return incomes[0] - 0

    left_deque.append(incomes[0])
    n -= 1

    while n > 0:
        left_deque.append(incomes[n])
        n -= 1

    if len(left_deque) % 2 == 0:
        return incomes[0] - (2 * left_deque[0])
    else:
        if len(left_deque) == 2:
            return incomes[0] - (left_deque[0] + left_deque[1])
        return incomes[0] + (2 * left_deque[0])

