from heapq import heappush, heappop

def is_good_drawing(left, right):
    combined = []
    for left_val, right_val in left:
        heappush(combined, (left_val, 0))
        heappush(combined, (right_val + 1, 1))
    for left_val, right_val in right:
        heappush(combined, (-left_val, 1))
        heappush(combined, (-right_val, 0))

    required = 0
    while combined:
        left_val, color = heappop(combined)
        if color == 0:
            required -= 1
            if required < 0:
                return (abs(required) > 1)
        else:
            required += 1
            if required > 1:
                return (required - 1) > 1

    return required % 2 == 0

def find_good_drawing(left, right):
    if not is_good_drawing(left, right):
        return -1

    result = [0] * len(left)
    for left_val, right_val in left:
        heappush(result, left_val)
    for left_val, right_val in right:
        if left_val > result[0]:
            heappushpop(result, right_val)
        elif left_val < result[0]:
