from collections import defaultdict

def find_region(a, b):
    n, m = len(a), len(b)
    g = defaultdict(lambda: defaultdict(int))

    for i in range(n):
        for j in range(m):
            g[i][j] = int(a[i], 2) | int(b[j], 2)

    visited = set()

    def bfs(i, j):
        queue = [(i, j)]
        visited.add((i, j))

        while queue:
            x, y = queue.pop(0)

            for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                if 0 <= nx < n and 0 <= ny < m and g[nx][ny] in visited:
                    return False

                if 0 <= nx < n and 0 <= ny < m:
                    visited.add((nx, ny))
                    queue.append((nx, ny))

        return True

    region_count = 0

    for i in range(n):
        for j in range(m):
            if g[i][j] and bfs(i, j):
                region_count += 1

    return region_count

