from collections import defaultdict

def find_parent(parent, node):
    if parent[node] != node:
        return find_parent(parent, parent[node])
    return parent[node]

def is_cousin(parent, a, b):
    return find_parent(parent, a) == find_parent(parent, b)

def number_of_acquaintance_pairs(graph, group_counts):
    group_count_pairs = defaultdict(list)
    for i in range(1, len(group_counts)):
        group_count_pairs[group_counts[i] - 1].append(i)

    group_acquaintance_counts = defaultdict(int)
    for node in range(len(group_count_pairs)):
        for group in group_count_pairs[node]:
            group_acquaintance_counts[group] += len(graph[node]) - 1

    cousins = 0
    for group_count in sorted(group_count_pairs.keys(), reverse=True):
        groups_left = group_count_pairs[group_count]
        # Only pair groups if both groups have at least one acquaintance
        if len(groups_left) > 1:
            cousins += sum(False if is_cousin(group_acquaintance_counts, group_1, group_2) else 1 for group_1, group_2 in combinations(groups_left, 2))

    return cousins
