from collections import defaultdict
from functools import lru_cache

def max_museums(n, m, d, cities):
    adj = defaultdict(list)
    for u, v in cities:
        adj[u-1].append(v-1)

    @lru_cache(maxsize=None)
    def dfs(city, last_day):
        if city >= n:
            return 0
        museums = d * [0]
        for to in adj[city]:
            visit_count = dfs(to, last_day)
            if visit_count > 0:
                for j in range(d):
                    if d-j > last_day or j == 0:
                        museums[j] = 1 if visit_count == 1 else visit_count
        return max(museums, visit_count+1)

    return dfs(0, d-1)

