        visited.add(group_id)
        for next_group_id in graph[group_id]:
            if next_group_id not in visited:
                dfs(next_group_id)
        for next_group_id in graph[group_id]:
            if next_group_id not in visited:
                res += 1
        visited.remove(group_id)

