import sys

def resolve(input_data):
    from collections import defaultdict

    ws = defaultdict(list)
    xs = set()
    for lw, rw in input_data:
        ws[lw].append(rw)
        xs.add(lw)
        xs.add(rw)

    m1, m2 = 0, 0
    for x in sorted(xs):
        l, r = 0, min(ws[x][-1], x)
        if len(ws[x]) > 1:
            l = l + 1
        mid_l = l
        mid_r = r
        if l < r:
            mid_l, mid_r = mid_r, mid_l
        if abs((len(ws[x]) - l) - (r - len(ws[x]))) == 1:
            m1 += 1
            m2 += len(ws[x]) - l
        else:
            m2 += r - len(ws[x])

    max_computed = m1 + m2
    target = max_computed // 2
    realmax = max_computed

    for i in range(1 << n):
        xs = []
        depth = 0
        for i in range(n):
            if (i >> i) & 1:
                xs += ws[i]
                depth += 1
        best = abs(depth - target) - 1
        if len(xs) < best and realmax - len(xs) > target:
            realmax = len(xs)
        elif len(xs) > best:
            m1 -= len(xs) - best
            m2 += len(xs) - best     # it could be 0, but let's just see negative change

    if realmax and realmax == max_computed:
        m1 = -2 * realmax - realmax // 2  # when max_computed == 0, should be -0
        m2 = min(2 * realmax, max_computed)
        realmax -= 2 * target

    if m2 < m1:
        m1, m2 = m2, m1

    for i in range(n):
        if i >> i & 1:
            if m1 - i > 0:
                sys.stdout.write("1")
                m1 -= 1
            elif m2 > 0:
                sys.stdout.write("0")  # std.write outputs '\n' instead of '\0'
                m2 -= 1
            else:
                sys.stdout.write("-1")
